const CATALOG = { en: {}, ru: { ...RU, ...RU_EXTRA, ...RU_MORE, ...RU_AUTH, ...RU_INTEGRATIONS, ...RU_MICRO, ...RU_ADMIN, ...RU_AUTH_SAMPLE, ...RU_LAST, ...RU_LANDING_EXTRA }, kk: { ...KK, ...KK_EXTRA, ...KK_MORE, ...KK_AUTH, ...KK_INTEGRATIONS, ...KK_MICRO, ...KK_PICK, ...KK_ADMIN, ...KK_AUTH_SAMPLE, ...KK_LAST, ...KK_LANDING_EXTRA } };
export function getLanguage() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (LANGUAGES.includes(saved)) return saved;
  } catch { /* storage can be disabled */ }
  const browser = (navigator.language || "en").slice(0, 2).toLowerCase();
  return browser === "kk" || browser === "ru" ? browser : "en";
}
export function t(text) { return CATALOG[getLanguage()]?.[text] || text; }

function translatedText(text) {
  const trimmed = text.trim();
  const value = t(trimmed);
  if (value === trimmed) return text;
  const start = text.indexOf(trimmed);
  return `${text.slice(0, start)}${value}${text.slice(start + trimmed.length)}`;
}

// Translate known interface labels in generated views as well as static HTML.
// Unknown copy remains readable in its source language until a catalog entry is added.
export function localize(root = document) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) {
    if (node.parentElement?.closest(".msgs, [data-no-translate]")) continue;
    node.nodeValue = translatedText(node.nodeValue);
  }
  root.querySelectorAll?.("[placeholder], [aria-label], [title]").forEach((el) => {
    for (const attr of ["placeholder", "aria-label", "title"]) {
      if (el.hasAttribute(attr)) el.setAttribute(attr, t(el.getAttribute(attr)));
    }
  });
  root.querySelectorAll?.('meta[name="description"], meta[property^="og:"]').forEach((el) => {
    const content = el.getAttribute("content");
    if (content) el.setAttribute("content", t(content));
  });
  document.documentElement.lang = getLanguage();
}

export function languageControl() {
  const current = getLanguage();
  const label = current === "ru" ? "Язык" : current === "kk" ? "Тіл" : "Language";
  const names = { en: "EN", ru: "RU", kk: "KZ" };
  return `<label class="language-control" aria-label="${label}"><span class="language-label">${label}</span><select data-language aria-label="${label}">${LANGUAGES.map((code) => `<option value="${code}" ${code === current ? "selected" : ""}>${names[code]}</option>`).join("")}</select></label>`;
}

export function initLanguageControl(root = document) {
  root.querySelectorAll("[data-language]").forEach((select) => {
    select.value = getLanguage();
    select.addEventListener("change", () => {
      try { localStorage.setItem(STORAGE_KEY, select.value); } catch { /* storage can be disabled */ }
      location.reload();
    });
  });
}
